//! Isolated demo commerce application over original Coins, Crypto and Oracle.
use commonware_codec::{Encode,ReadExt};
use commonware_cryptography::{sha256::Digest,Hasher,Sha256};
use futures::executor::block_on;
use nunchi_common::{Address,Authorization,RuntimeContext,StateError,StateStore,VecEventSink};
use nunchi_crypto::PrivateKey;
use nunchi_coins::{AllocationGenesis,CoinId,CoinOperation,CoinSpec,CoinsGenesis,Ledger,TokenFactory,TokenGenesis,TokenName,TokenSymbol,Transaction};
use nunchi_oracle::{IntervalKey,NamespaceId,OracleLedger,OracleOperation,Transaction as OracleTransaction};
use serde::{Serialize,Deserialize};
use serde_json::{json,Value};
use std::{cell::RefCell,collections::BTreeMap};
const SDK:&str="eea35ced709f68c15d6fbc8bcc754696a7e44374";
const SUPPLY:u64=50000;
#[derive(Clone,Default,Debug,Eq,PartialEq)]struct Memory(BTreeMap<Digest,Vec<u8>>);
impl StateStore for Memory{
 async fn get(&self,key:&Digest)->Result<Option<Vec<u8>>,StateError>{Ok(self.0.get(key).cloned())}
 fn set(&mut self,key:Digest,value:Vec<u8>){self.0.insert(key,value);}
 fn remove(&mut self,key:Digest){self.0.remove(&key);}
}
fn key(i:usize)->PrivateKey{PrivateKey::from_seed(2026101800+i as u64)}
fn address(i:usize)->Address{Address::external(&key(i).public_key())}
fn enc(v:&impl Encode)->String{hex::encode(v.encode().as_ref())}
fn transaction(s:&str)->Result<Transaction,String>{if s.len()>100000{return Err("Transaction exceeds the bridge limit.".into());}let bytes=hex::decode(s).map_err(|_|"Invalid transaction hex.")?;let mut cursor=bytes.as_slice();let tx=Transaction::read(&mut cursor).map_err(|e|e.to_string())?;if !cursor.is_empty(){return Err("Trailing transaction bytes.".into());}Ok(tx)}
fn index(v:&Value,k:&str,max:usize)->Result<usize,String>{v[k].as_u64().filter(|n|*n<(max as u64)).map(|n|n as usize).ok_or(format!("Invalid {k}."))}
#[derive(Clone,Serialize,Deserialize)]struct Policy{allocation_minor:u64,maximum_minor:u64,approval_above_minor:u64,allowed_providers:Vec<usize>,paused:bool,version:u64}
struct Session{id:String,coin:CoinId,coins:Ledger<Memory>,oracle:OracleLedger<Memory>,namespace:NamespaceId,policies:Vec<Policy>,prices:Vec<u64>,requests:Vec<Value>,timeline:Vec<Value>,oracle_records:Vec<Value>,duplicates:u64}
impl Session{
 fn new(id:&str)->Result<Self,String>{
  if id.len()<8||id.len()>80||!id.bytes().all(|c|c.is_ascii_alphanumeric()||b"-_".contains(&c)){return Err("Invalid session ID.".into());}
  let spec=CoinSpec::new(TokenSymbol::new("DCR").unwrap(),TokenName::new(format!("Isolated demo credits {id}")).unwrap(),2,SUPPLY as u128,Some(SUPPLY as u128));
  let coin=TokenFactory::derive_coin_id(&address(10),0,&spec);
  let mut coins=Ledger::new(Memory::default());
  block_on(coins.apply_genesis(&CoinsGenesis{account_policies:vec![],tokens:vec![TokenGenesis{issuer:address(10),spec,allocations:(0..5).map(|i|AllocationGenesis{account:address(i),amount:10000}).collect()}],fees:None})).map_err(|e|e.to_string())?;
  if block_on(coins.token(&coin)).map_err(|e|e.to_string())?.is_none(){return Err("SDK genesis token readback failed.".into());}
  Ok(Self{id:id.into(),coin,coins,oracle:OracleLedger::new(Memory::default()),namespace:NamespaceId(Sha256::hash(&[b"agent-payment-network/",id.as_bytes()])),policies:(0..5).map(|i|Policy{allocation_minor:10000,maximum_minor:2000,approval_above_minor:1500,allowed_providers:if i==2{vec![2]}else{vec![i,2]},paused:false,version:1}).collect(),prices:vec![1500,500,200,300,1200],requests:vec![],timeline:vec![],oracle_records:vec![],duplicates:0})
 }
 fn balances(&self)->Result<Vec<Value>,String>{(0..11).map(|i|Ok(json!({"index":i,"account":enc(&address(i)),"public_key":enc(&key(i).public_key()),"balance_minor":block_on(self.coins.balance(&address(i),&self.coin)).map_err(|e|e.to_string())?.to_string(),"nonce":block_on(self.coins.nonce(&address(i))).map_err(|e|e.to_string())?}))).collect()}
 fn spent(&self,agent:usize)->u64{self.requests.iter().filter(|r|r["agent_index"]==agent&&r.get("payment").is_some()).map(|r|r["amount_minor"].as_u64().unwrap_or(0)).sum()}
 fn log(&mut self,n:usize,stage:&str,source:&str,text:&str){let e=json!({"request_id":self.requests[n]["request_id"],"stage":stage,"source":source,"text":text,"sequence":self.timeline.len()+1});self.timeline.push(e.clone());self.requests[n]["history"].as_array_mut().unwrap().push(e);}
 fn snapshot(&self)->Result<Value,String>{Ok(json!({"session_id":self.id,"sdk_commit":SDK,"asset_id":enc(&self.coin),"asset_symbol":"DCR","decimals":2,"opening_supply_minor":SUPPLY,"fee_minor":0,"balances":self.balances()?,"policies":self.policies,"prices_minor":self.prices,"requests":self.requests,"timeline":self.timeline,"oracle_records":self.oracle_records,"duplicate_attempts":self.duplicates}))}
 fn locate(&self,id:&str)->Result<usize,String>{self.requests.iter().position(|r|r["request_id"]==id).ok_or("Request not found in this session.".into())}
 fn request(&mut self,a:usize,p:usize,retry:Option<String>)->Result<usize,String>{if self.requests.len()>=128{return Err("Export and reset after 128 service requests.".into());}let n=self.requests.len();self.requests.push(json!({"request_id":format!("REQ-{}-{:03}",self.id,n+1),"session_id":self.id,"agent_index":a,"provider_index":p,"task_id":format!("TASK-{:03}",n+1),"status":"requested","amount_minor":0,"history":[],"manual_approved":false,"retry_of":retry}));self.log(n,"requested","application","Agent requested a simulated paid service.");Ok(n)}
 fn policy_error(&self,n:usize)->Option<String>{let r=&self.requests[n];let a=r["agent_index"].as_u64().unwrap() as usize;let p=r["provider_index"].as_u64().unwrap() as usize;let amount=r["amount_minor"].as_u64().unwrap();let rule=&self.policies[a];
 if rule.paused{Some("Agent is paused by application policy.".into())}else if !rule.allowed_providers.contains(&p){Some("Provider is not approved for this agent.".into())}else if amount>rule.maximum_minor{Some("Quote exceeds the maximum single purchase.".into())}else if self.spent(a).saturating_add(amount)>rule.allocation_minor{Some("Quote exceeds the remaining spending allocation.".into())}else{None}}
 fn authorize(&mut self,n:usize,manual:bool)->Result<(),String>{let status=self.requests[n]["status"].as_str().unwrap_or("");if status!="quoted"&&status!="awaiting_approval"{return Err("Quote this request before authorizing it.".into());}
 if let Some(reason)=self.policy_error(n){self.requests[n]["status"]=json!("rejected");self.requests[n]["rejection_reason"]=json!(reason.clone());self.log(n,"rejected","application",&format!("{reason} No Coins transaction was submitted."));return Ok(());}
 let a=self.requests[n]["agent_index"].as_u64().unwrap() as usize;let amount=self.requests[n]["amount_minor"].as_u64().unwrap();
 if amount>self.policies[a].approval_above_minor&&!manual{self.requests[n]["status"]=json!("awaiting_approval");self.log(n,"awaiting_approval","application","Operator approval is required before a transaction can be signed.");return Ok(());}
 self.requests[n]["manual_approved"]=json!(manual);self.requests[n]["policy_version"]=json!(self.policies[a].version);self.requests[n]["status"]=json!("approved");self.log(n,"approved","application","Current application policy permits this purchase.");Ok(())}
 fn signed_json(tx:&Transaction)->Result<Value,String>{let (pk,sig)=match &tx.authorization{Authorization::Single{signer,signature}=>(enc(signer.as_ref()),enc(signature)),_=>return Err("Expected a single demo signer.".into())};let (coin,from,to,amount)=match &tx.payload.operation{CoinOperation::Transfer{coin,from,to,amount}=>(coin,from,to,amount),_=>return Err("Only demo transfers are supported.".into())};Ok(json!({"signed_transaction":enc(tx),"transaction_id":enc(&tx.digest()),"sender":enc(from),"recipient":enc(to),"asset_id":enc(coin),"amount_minor":amount.to_string(),"nonce":tx.payload.nonce,"public_key":pk,"signature":sig,"signature_valid":tx.verify().is_ok(),"operation":"CoinOperation::Transfer"}))}
 fn sign(&mut self,n:usize)->Result<(),String>{if self.requests[n]["status"]!="approved"{return Err("The request is not approved.".into());}if let Some(e)=self.policy_error(n){return Err(e);}let a=self.requests[n]["agent_index"].as_u64().unwrap() as usize;let p=self.requests[n]["provider_index"].as_u64().unwrap() as usize;let amount=self.requests[n]["amount_minor"].as_u64().unwrap();let nonce=block_on(self.coins.nonce(&address(a))).map_err(|e|e.to_string())?;
 let tx=Transaction::sign(&key(a),nonce,CoinOperation::Transfer{coin:self.coin,from:address(a),to:address(p+5),amount:amount as u128});tx.verify().map_err(|e|e.to_string())?;
 self.requests[n]["transaction"]=Self::signed_json(&tx)?;self.requests[n]["status"]=json!("signed");self.log(n,"signed","sdk","Coins transaction signed and verified by original SDK cryptography.");Ok(())}
 fn duplicate(&mut self,n:usize){self.duplicates+=1;self.log(n,"duplicate_prevented","application","Stable request ID already has an applied payment. Reused original result; no second transfer submitted.");}
 fn apply(&mut self,n:usize)->Result<(),String>{
 if self.requests[n].get("payment").is_some(){self.duplicate(n);return Ok(());}if self.requests[n]["status"]!="submitted"{return Err("Submit the signed request before applying it.".into());}if let Some(reason)=self.policy_error(n){self.requests[n]["status"]=json!("rejected");self.requests[n]["rejection_reason"]=json!(reason.clone());self.log(n,"rejected","application",&format!("{reason} No ledger operation applied."));return Ok(());}
 let tx=transaction(self.requests[n]["transaction"]["signed_transaction"].as_str().unwrap())?;tx.verify().map_err(|e|e.to_string())?;let a=self.requests[n]["agent_index"].as_u64().unwrap() as usize;let p=self.requests[n]["provider_index"].as_u64().unwrap() as usize;let amount=self.requests[n]["amount_minor"].as_u64().unwrap();
 let before=self.balances()?;let mut next=self.coins.clone();let mut events=VecEventSink::new();
 match block_on(next.apply_transaction(&tx,&mut events)){Err(e)=>{self.requests[n]["status"]=json!("failed");self.requests[n]["execution_error"]=json!(e.to_string());self.log(n,"failed","sdk",&format!("SDK Coins rejected execution: {e}. Staged state discarded."));return Ok(())},Ok(())=>{}}
 let sender=block_on(next.balance(&address(a),&self.coin)).map_err(|e|e.to_string())?;let recipient=block_on(next.balance(&address(p+5),&self.coin)).map_err(|e|e.to_string())?;
 if sender+amount as u128!=before[a]["balance_minor"].as_str().unwrap().parse::<u128>().unwrap()||recipient!=before[p+5]["balance_minor"].as_str().unwrap().parse::<u128>().unwrap()+amount as u128{return Err("SDK balance readback did not match the transfer.".into());}
 self.coins=next;let after=self.balances()?;self.requests[n]["payment"]=json!({"execution":"applied_to_local_sdk_ledger","balance_readback_matches":true,"before":before,"after":after,"sdk_events":events.events().iter().map(|e|json!({"name":String::from_utf8_lossy(&e.name),"payload_hex":hex::encode(&e.value)})).collect::<Vec<_>>()});self.requests[n]["status"]=json!("applied");self.log(n,"applied","sdk","Original Coins ledger applied the signed transfer. Sender and recipient balances were read back.");Ok(())}
 fn fulfill(&mut self,n:usize)->Result<(),String>{if self.requests[n]["status"]=="fulfilled"{return Ok(());}if self.requests[n]["status"]!="applied"{return Err("The service cannot fulfill an unpaid request.".into());}
 let a=self.requests[n]["agent_index"].as_u64().unwrap() as usize;let payload=json!({"session_id":self.id,"request_id":self.requests[n]["request_id"],"task_id":self.requests[n]["task_id"],"agent_index":a,"provider_index":self.requests[n]["provider_index"],"amount_minor":self.requests[n]["amount_minor"],"transaction_id":self.requests[n]["transaction"]["transaction_id"],"authorization":"Application policy approved","manual_approved":self.requests[n]["manual_approved"],"policy_version":self.requests[n]["policy_version"],"fulfillment":"Simulated service response; no external merchant contacted"});
 let nonce=self.oracle_records.iter().filter(|r|r["payload"]["agent_index"]==a).count() as u64;let bucket=IntervalKey::new(0);let tx=OracleTransaction::sign(&key(a),nonce,OracleOperation::AppendRecord{namespace:self.namespace,interval:bucket,payload:serde_json::to_vec(&payload).unwrap(),proof:None});tx.verify().map_err(|e|e.to_string())?;
 let mut next=self.oracle.clone();block_on(next.apply_transaction(&tx,RuntimeContext{height:self.oracle_records.len() as u64+1,timestamp_ms:(n as u64+1)*1000,..Default::default()})).map_err(|e|e.to_string())?;let records=block_on(next.records_by_namespace(&self.namespace,bucket,bucket)).map_err(|e|e.to_string())?;let record=records.last().ok_or("Oracle returned no service record.")?;let stored=block_on(next.record(&record.id)).map_err(|e|e.to_string())?.ok_or("Oracle service record readback failed.")?;let OracleOperation::AppendRecord{payload:original,..}=&tx.payload.operation;if stored.payload!=*original{return Err("Oracle payload readback differs.".into());}
 let evidence=json!({"record_id":enc(&stored.id),"namespace":enc(&stored.namespace),"writer":enc(&stored.writer),"payload":payload,"payload_hex":hex::encode(&stored.payload),"signed_transaction":enc(&tx),"transaction_id":enc(&tx.digest()),"signature_valid":tx.verify().is_ok(),"readback_matches":true});
 self.oracle=next;self.oracle_records.push(evidence.clone());self.requests[n]["service_record"]=evidence;self.requests[n]["status"]=json!("fulfilled");self.log(n,"fulfilled","application + SDK","Simulated service delivered; related signed Oracle record written and read back.");Ok(())}
 fn handle(&mut self,input:&Value)->Result<Value,String>{
 let cmd=input["command"].as_str().unwrap_or("");if cmd=="reset"{*self=Self::new(input["session_id"].as_str().unwrap_or(""))?;return self.snapshot();}if cmd=="snapshot"{return self.snapshot();}
 if cmd=="request"{let a=index(input,"agent_index",5)?;let p=index(input,"provider_index",5)?;let n=self.request(a,p,None)?;return Ok(json!({"request_id":self.requests[n]["request_id"],"snapshot":self.snapshot()?}));}
 if cmd=="policy"{let a=index(input,"agent_index",5)?;let mut p:Policy=serde_json::from_value(input["policy"].clone()).map_err(|e|e.to_string())?;if p.allocation_minor>10000000||p.maximum_minor>10000000||p.approval_above_minor>10000000||p.allowed_providers.iter().any(|p|*p>=5){return Err("Policy values exceed demo bounds.".into());}p.version=self.policies[a].version+1;self.policies[a]=p;for n in 0..self.requests.len(){if self.requests[n]["agent_index"]==a&&matches!(self.requests[n]["status"].as_str(),Some("approved"|"signed"|"submitted"|"awaiting_approval")){self.requests[n]["status"]=json!("quoted");self.requests[n].as_object_mut().unwrap().remove("transaction");self.requests[n]["manual_approved"]=json!(false);self.log(n,"quoted","application","Policy changed; prior approval/signature discarded. Reauthorize at the current policy.");}}return self.snapshot();}
 if cmd=="price"{let p=index(input,"provider_index",5)?;let price=input["amount_minor"].as_u64().filter(|n|*n>0&&*n<=10000000).ok_or("Price must be a positive integer minor-unit amount.")?;self.prices[p]=price;return self.snapshot();}
 if cmd=="verify"{let mut tx=transaction(input["signed_transaction"].as_str().unwrap_or(""))?;if let Some(amount)=input["edited_amount_minor"].as_u64(){let CoinOperation::Transfer{amount:original,..}=&mut tx.payload.operation else{return Err("Not a transfer.".into())};*original=amount as u128;}let result=tx.verify();return Ok(json!({"valid":result.is_ok(),"error":result.err().map(|e|e.to_string())}));}
 if cmd=="probe"{let mut tx=transaction(input["signed_transaction"].as_str().unwrap_or(""))?;if let Some(offset)=input["nonce_offset"].as_u64(){if offset>10{return Err("Probe nonce offset exceeds demo bounds.".into());}let a=index(input,"agent_index",5)?;let amount=input["amount_minor"].as_u64().unwrap_or(1);tx=Transaction::sign(&key(a),block_on(self.coins.nonce(&address(a))).map_err(|e|e.to_string())?+offset,CoinOperation::Transfer{coin:self.coin,from:address(a),to:address(5),amount:amount as u128});}let verification=tx.verify();let mut next=self.coins.clone();let outcome=verification.map_err(|e|e.to_string()).and_then(|_|block_on(next.apply_transaction(&tx,VecEventSink::new())).map_err(|e|e.to_string()));return Ok(json!({"would_apply":outcome.is_ok(),"error":outcome.err(),"state_committed":false,"scope":"SDK validation on a discarded local ledger clone"}));}
 let n=self.locate(input["request_id"].as_str().unwrap_or(""))?;
 match cmd{
 "quote"=>{if self.requests[n]["status"]!="requested"{return Err("Request is already quoted.".into());}let p=self.requests[n]["provider_index"].as_u64().unwrap() as usize;self.requests[n]["amount_minor"]=json!(self.prices[p]);self.requests[n]["status"]=json!("quoted");self.log(n,"quoted","application","Simulated provider returned an illustrative quote.");},
 "authorize"=>self.authorize(n,false)?,
 "approve"=>{if self.requests[n]["status"]!="awaiting_approval"{return Err("This request is not awaiting approval.".into());}self.authorize(n,true)?;},
 "reject"=>{if !matches!(self.requests[n]["status"].as_str(),Some("awaiting_approval"|"approved"|"quoted")){return Err("This request cannot be rejected now.".into());}self.requests[n]["status"]=json!("rejected");self.requests[n]["rejection_reason"]=json!("Operator rejected the request.");self.log(n,"rejected","application","Operator rejected the request before SDK submission.");},
 "sign"=>self.sign(n)?,
 "submit"=>{if self.requests[n]["status"]!="signed"{return Err("Sign before submission.".into());}let tx=transaction(self.requests[n]["transaction"]["signed_transaction"].as_str().unwrap())?;tx.verify().map_err(|e|e.to_string())?;self.requests[n]["status"]=json!("submitted");self.log(n,"submitted","application","Signed transaction submitted to the local in-process execution path; balances have not changed.");},
 "apply"=>self.apply(n)?,
 "fulfill"=>self.fulfill(n)?,
 "duplicate"=>{if self.requests[n].get("payment").is_none(){return Err("Apply the original payment before retrying its stable request ID.".into());}self.duplicate(n);},
 "retry"=>{if self.requests[n].get("payment").is_some(){self.duplicate(n);return Ok(json!({"request_id":self.requests[n]["request_id"],"snapshot":self.snapshot()?}));}if !matches!(self.requests[n]["status"].as_str(),Some("rejected"|"failed")){return Err("Only rejected or failed attempts can create a new retry request.".into());}let a=self.requests[n]["agent_index"].as_u64().unwrap() as usize;let p=self.requests[n]["provider_index"].as_u64().unwrap() as usize;let old=self.requests[n]["request_id"].as_str().unwrap().to_string();let next=self.request(a,p,Some(old))?;return Ok(json!({"request_id":self.requests[next]["request_id"],"snapshot":self.snapshot()?}));},
 _=>return Err("Unknown payment command.".into())}
 Ok(json!({"request_id":self.requests[n]["request_id"],"snapshot":self.snapshot()?}))
 }
}
thread_local!{static STATE:RefCell<Session>=RefCell::new(Session::new("uninitialized").unwrap());static OUTPUT:RefCell<Vec<u8>>=const{RefCell::new(Vec::new())};}
#[no_mangle]pub extern "C" fn smoke()->u32{let tx=Transaction::sign(&key(0),0,CoinOperation::Transfer{coin:CoinId(Sha256::hash(&[b"smoke"])),from:address(0),to:address(5),amount:1});u32::from(tx.verify().is_ok())}
#[no_mangle]pub extern "C" fn alloc(len:usize)->*mut u8{if len==0||len>500000{return std::ptr::null_mut();}Box::into_raw(vec![0u8;len].into_boxed_slice()) as *mut u8}
/// # Safety
/// Host passes a fresh alloc pointer with its exact length once.
#[no_mangle]pub unsafe extern "C" fn process(ptr:*mut u8,len:usize){let bytes=unsafe{Box::from_raw(std::ptr::slice_from_raw_parts_mut(ptr,len))};let result=serde_json::from_slice::<Value>(&bytes).map_err(|e|e.to_string()).and_then(|v|STATE.with(|s|s.borrow_mut().handle(&v)));let reply=match result{Ok(v)=>json!({"ok":true,"data":v}),Err(e)=>json!({"ok":false,"error":e})};OUTPUT.with(|out|*out.borrow_mut()=serde_json::to_vec(&reply).unwrap());}
#[no_mangle]pub extern "C" fn output_ptr()->*const u8{OUTPUT.with(|o|o.borrow().as_ptr())}
#[no_mangle]pub extern "C" fn output_len()->usize{OUTPUT.with(|o|o.borrow().len())}

